sys_script_include.script:
var jinji_approval = Class.create();
jinji_approval.prototype = {
    initialize: function() {},

    request: function(sys_id) {
        var gr = new GlideRecord('x_1882833_organi_0_meisai');
        gr.addQuery('sinsei_number', sys_id);
        gr.addQuery('kenmu_number', '主務');
        gr.addQuery('state', '!=', 20);
		gr.addQuery('active', true);
        gr.query();

        if (!gr.hasNext()) {
            return '1';
        }

        while (gr.next()) {
            if (gs.nil(gr.hatureibi)) {
                return '2';
            }

            var varDate = gr.hatureibi;

            var today = new GlideDateTime();
            var gdt = new GlideDateTime(today.getLocalDate() + " 00:00:00");

            var target = new GlideDateTime(varDate + " 00:00:00");

            var diffMs = target.getNumericValue() - gdt.getNumericValue();

            var diffDays = diffMs / (1000 * 60 * 60 * 24);

            if (diffDays < 0) {
				return '3';
            }
        }
        return '0';

    },

    requestDelete: function(sys_id) {
        var gr = new GlideRecord('x_1882833_organi_0_meisai');
        gr.addQuery('sinsei_number', sys_id);
		gr.addQuery('active', true);
        gr.addEncodedQuery('kenmu_number=新規入力欄^ORkenmu_number=入力中');
        gr.query();

		while(gr.next()){
			gr.active = false;
			gr.update();
		}
    },

    type: 'jinji_approval'
};
